// ── Normalización de dirección de país ──────────────────────────────────────
function normalizeCountryAddress(value) {
  if (typeof value !== 'string') return value;
  return value.replace(
    /\bVEN\s+Venezuela\s*\(Bolivarian Republic of\)/gi,
    'VEN - Venezuela'
  );
}
// ────────────────────────────────────────────────────────────────────────────

function norm(r) {
  var raw = String(r.website || r.WEBSITE || '').trim();
  var web = raw ? (/^https?:\/\//i.test(raw) ? raw : 'https://' + raw) : '';
  return {
    name:      r.name      || r.NAME      || 'Sin nombre',
    rif:       r.rif       || r.RIF       || '',
    sector:    r.Sector    || r.SECTOR    || '',
    servicios: r.Servicios || r.SERVICIOS || '',
    ciudad:    r.CIUDAD    || r.ciudad    || '',
    estado:    r.state     || r.STATE     || '',
    phone:     r.phone     || r.PHONE     || '',
    street:    normalizeCountryAddress(String(r.street || r.STREET || '')),
    website:   web
  };
