var agent = safe(function(){ return $('Interactive Intent Agent3').first().json; }, {});

// filas reales devueltas por MySQL (alwaysOutputData -> 1 item vacio si 0)
var rows = safe(function(){
  return $('MySQL Query3').all().map(function(i){ return i.json; })
         .filter(function(j){ return j && Object.keys(j).length > 0; });
}, []);
var nResultados = rows.length;

var isCommand   = safe(function(){ return $('Detect Command').first().json.isCommand; }, false);
var wrongPw     = safe(function(){ return !!$('Wrong Password').first().json; }, false);
var searchReady = String(parse.isSearchReady) === 'true';

// --- estado de parseo del JSON del agente (observabilidad, obs. 3) ---
//  no_json  = respuesta conversacional legitima (sin JSON)
//  ok       = el modelo emitio JSON limpio
//  recovered= JSON malformado pero rescatado por Parse Intent JSON3
//  failed   = habia JSON pero no se pudo parsear ni rescatar
var agentRaw = agent.output || '';
var bStart = agentRaw.indexOf('{');
var bEnd = agentRaw.lastIndexOf('}');
var parse_status;
if (bStart === -1 || bEnd <= bStart) {
  parse_status = 'no_json';
} else {
  var okClean = false;
  try { JSON.parse(agentRaw.substring(bStart, bEnd + 1)); okClean = true; } catch(e) {}
  if (okClean) parse_status = 'ok';
  else if (searchReady) parse_status = 'recovered';
  else parse_status = 'failed';
}
var parse_ok = (parse_status === 'ok' || parse_status === 'no_json');
var error_log_val = (parse_status === 'failed') ? 'json_parse_failed' : null;

// --- inferir resultado_tipo por el camino ejecutado ---
var resultado_tipo;
if (isCommand)          resultado_tipo = wrongPw ? 'comando_error' : 'comando';
else if (!searchReady)  resultado_tipo = 'conversation';
else if (nResultados === 0) resultado_tipo = 'sin_resultados';
else                    resultado_tipo = 'results';

var meta = body.meta || pre.meta || {};
var wp   = meta.wp || {};

var t0 = pre.t0 || null;
var tiempo_respuesta_ms = t0 ? (Date.now() - t0) : null;

var respuesta_ia = agent.output || parse.conversationalText || null;

var output = safe(function(){ return $json.output; }, null)
          || safe(function(){ return $('Format Cards2').first().json.output; }, null)
          || safe(function(){ return $('Code in JavaScript1').first().json.output; }, null)
          || null;

var tokens = 0;
try { tokens = agent.response_metadata.tokenUsage.totalTokens; }
catch(e){ tokens = respuesta_ia ? Math.ceil(String(respuesta_ia).length / 4) : 0; }

var exec = null; try { exec = $execution.id; } catch(e){}

return [{ json: {
